import{money,esc,metrics,dayShift,daysBetween,clamp,today}from'./core.mjs';
export function dailySeries(data,id=null,days=28){return Array.from({length:days},(_,i)=>{const date=dayShift(data.asOf,i-days+1),rows=data.sales.filter(s=>s.date===date&&(!id||s.productId===id));return{date,units:rows.reduce((a,s)=>a+s.units,0),views:rows.reduce((a,s)=>a+s.views,0),revenue:rows.reduce((a,s)=>a+s.revenue,0),margin:rows.reduce((a,s)=>a+s.revenue-s.units*(data.products.find(p=>p.id===s.productId)?.cost||0),0)};});}
export function advancedMetrics(data,days=7){const series=dailySeries(data,null,days),m=metrics(data,null,days),oldRows=data.sales.filter(s=>daysBetween(data.asOf,s.date)>=days&&daysBetween(data.asOf,s.date)<days*2),prior=oldRows.reduce((a,s)=>a+s.revenue,0),stockCost=data.products.reduce((a,p)=>a+p.stock*p.cost,0),stockRetail=data.products.reduce((a,p)=>a+p.stock*p.price,0),atRisk=data.products.filter(p=>p.expiresIn<=5&&p.stock>metrics(data,p.id).rate*p.expiresIn),std=Math.sqrt(series.reduce((a,s)=>a+(s.revenue-m.revenue/days)**2,0)/days);return{...m,change:prior?(m.revenue-prior)/prior:null,stockCost,stockRetail,inventoryMargin:stockRetail-stockCost,avgDaily:m.revenue/days,marginRate:m.revenue?m.margin/m.revenue:0,avgUnit:m.units?m.revenue/m.units:0,unitMargin:m.units?m.margin/m.units:0,zeroSales:data.products.filter(p=>metrics(data,p.id,days).units===0).length,riskCount:atRisk.length,riskCost:atRisk.reduce((a,p)=>a+Math.max(0,p.stock-metrics(data,p.id).rate*p.expiresIn)*p.cost,0),lowStock:data.products.filter(p=>metrics(data,p.id).daysCover<p.leadDays).length,weakCards:data.products.filter(p=>p.completeness<80||p.photos<2).length,avgCard:data.products.reduce((a,p)=>a+p.completeness,0)/data.products.length,cv:m.revenue?std/(m.revenue/days):0,daysWithSales:series.filter(s=>s.revenue>0).length,consented:data.segments.reduce((a,s)=>a+s.consented,0),customers:data.segments.reduce((a,s)=>a+s.count,0)};}
function estimate(train,date,method){const recent=train.slice(-7),mean=recent.reduce((a,x)=>a+x.units,0)/Math.max(1,recent.length);if(method==='average')return mean;const weekday=new Date(date+'T12:00:00Z').getUTCDay(),same=train.filter(x=>new Date(x.date+'T12:00:00Z').getUTCDay()===weekday).slice(-4);const seasonal=same.reduce((a,x)=>a+x.units,0)/Math.max(1,same.length);return .6*mean+.4*(same.length?seasonal:mean);}
export function forecast(data,id,horizon=7,method='weekday'){const p=data.products.find(p=>p.id===id);if(!p)throw Error('Товар не найден');const records=data.sales.filter(s=>s.productId===id).sort((a,b)=>a.date.localeCompare(b.date));if(records.length<14)return{valid:false,reason:'Для прогноза нужны минимум 14 дневных наблюдений товара.'};const range=daysBetween(data.asOf,records[0].date)+1;if(range>3650)return{valid:false,reason:'История слишком длинная для локального прогноза.'};const series=dailySeries(data,id,Math.min(range,90));const tests=[];for(let i=Math.max(7,series.length-7);i<series.length;i++){const pred=estimate(series.slice(0,i),series[i].date,method);tests.push({actual:series[i].units,pred,error:Math.abs(pred-series[i].units)});}const mae=tests.reduce((a,t)=>a+t.error,0)/tests.length,den=tests.reduce((a,t)=>a+t.actual,0),wape=den?tests.reduce((a,t)=>a+t.error,0)/den:null;const mean=series.slice(-7).reduce((a,x)=>a+x.units,0)/7;const future=Array.from({length:clamp(horizon,1,30)},(_,i)=>{const date=dayShift(data.asOf,i+1),units=estimate(series,date,method),delta=Math.max(mae*1.5,Math.sqrt(Math.max(mean,.2))*.6)*Math.sqrt(1+i/7);return{date,units,low:Math.max(0,units-delta),high:units+delta};});const total=future.reduce((a,f)=>a+f.units,0),low=future.reduce((a,f)=>a+f.low,0),high=future.reduce((a,f)=>a+f.high,0);const usableStock=Math.min(p.stock,future.slice(0,Math.floor(p.expiresIn)).reduce((a,x)=>a+x.units,0));return{valid:true,series:series.slice(-14),future,total,low,high,mae,wape,tests,mean,stock:p.stock,usableStock,needed:Math.max(0,Math.ceil(total-usableStock)),daysCover:mean?Math.min(p.stock/mean,p.expiresIn):null,method};}
export function abc(data,days=28){const rows=data.products.map(p=>({p,...metrics(data,p.id,days)})).sort((a,b)=>b.revenue-a.revenue);const sum=rows.reduce((a,r)=>a+r.revenue,0);let before=0;return rows.map(r=>{const share=sum?r.revenue/sum:0,group=before<.8?'A':before<.95?'B':'C';before+=share;return{...r,share,cumulative:before,group};});}
const colors=['#327d76','#a5b4a0','#ce9f79','#a89abb','#d6c495','#739ba5','#bd8d8d','#7e9d6d'];
export function linePlot(rows,keys=['revenue'],labels=['Выручка'],height=230){const w=800,h=height,pad=35,max=Math.max(1,...rows.flatMap(r=>keys.map(k=>r[k]||0)))*1.12;return`<svg viewBox="0 0 ${w} ${h+30}" class="data-chart" role="img" aria-label="${esc(labels.join(', '))}, ${rows.length} дней">${[.25,.5,.75,1].map(f=>`<line x1="${pad}" y1="${h-h*f}" x2="780" y2="${h-h*f}" stroke="#e3e7dd" stroke-dasharray="3 5"/><text x="31" y="${h-h*f+4}" text-anchor="end" fill="#7c8b7e" font-size="10">${Math.round(max*f/1000)}к</text>`).join('')}${keys.map((k,j)=>`<polyline points="${rows.map((r,i)=>`${pad+i*(w-pad-20)/Math.max(1,rows.length-1)},${h-(r[k]||0)/max*(h-16)}`).join(' ')}" fill="none" stroke="${colors[j]}" stroke-width="3" stroke-linejoin="round"/>`).join('')}${keys.map((k,j)=>rows.map((r,i)=>`<circle cx="${pad+i*(w-pad-20)/Math.max(1,rows.length-1)}" cy="${h-(r[k]||0)/max*(h-16)}" r="3" fill="${colors[j]}"><title>${r.date}: ${esc(labels[j])} ${money(r[k]||0)}</title></circle>`).join('')).join('')}${rows.filter((_,i)=>i%Math.ceil(rows.length/7)===0||i===rows.length-1).map(r=>`<text x="${pad+rows.indexOf(r)*(w-pad-20)/Math.max(1,rows.length-1)}" y="${h+23}" text-anchor="middle" fill="#7c8b7e" font-size="11">${r.date.slice(8)}.${r.date.slice(5,7)}</text>`).join('')}</svg><div class="legend">${labels.map((x,i)=>`<span><i style="background:${colors[i]}"></i>${esc(x)}</span>`).join('')}</div>`;}
export function donut(data){const groups={};for(const p of data.products)groups[p.category]=(groups[p.category]||0)+metrics(data,p.id,28).revenue;const rows=Object.entries(groups),total=rows.reduce((a,r)=>a+r[1],0);let offset=0;return`<div class="donut-layout"><svg viewBox="0 0 210 210" role="img" aria-label="Доли категорий в выручке за 28 дней"><circle cx="105" cy="105" r="76" fill="none" stroke="#edf0e8" stroke-width="22"/>${rows.map(([name,value],i)=>{const frac=total?value/total:0,start=offset;offset+=frac;return`<circle cx="105" cy="105" r="76" fill="none" stroke="${colors[i%colors.length]}" stroke-width="22" stroke-dasharray="${frac*477.52} ${477.52*(1-frac)}" stroke-dashoffset="${-start*477.52}" transform="rotate(-90 105 105)"><title>${esc(name)}: ${money(value)}</title></circle>`;}).join('')}<text x="105" y="104" text-anchor="middle" fill="#24534d" font-size="27" font-family="Georgia">${rows.length}</text><text x="105" y="126" text-anchor="middle" fill="#7d8f7c" font-size="11">категорий</text></svg><div class="donut-legend">${rows.map(([name,val],i)=>`<span><i style="background:${colors[i%colors.length]}"></i><b>${esc(name)}</b><small>${total?Math.round(val/total*100):0}%</small></span>`).join('')}</div></div>`;}
export function heatmap(data){const rows=data.products.map(p=>{const days=Array.from({length:7},(_,day)=>{const ss=data.sales.filter(s=>s.productId===p.id&&new Date(s.date+'T12:00:00Z').getUTCDay()===(day+1)%7);return ss.reduce((a,s)=>a+s.units,0)/Math.max(1,ss.length);});return{p,days};});const max=Math.max(1,...rows.flatMap(r=>r.days));return`<div class="heatmap"><div class="heatrow heathead"><span></span>${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(d=>`<span>${d}</span>`).join('')}</div>${rows.map(r=>`<div class="heatrow"><span title="${esc(r.p.name)}">${esc(r.p.name)}</span>${r.days.map(v=>`<span style="background:rgba(44,119,109,${.08+v/max*.75});color:${v/max>.5?'white':'#477067'}" title="Среднее ${v.toFixed(1)} ед./день">${v.toFixed(1)}</span>`).join('')}</div>`).join('')}</div>`;}
export function scatter(data){const rows=data.products.map(p=>({p,m:metrics(data,p.id)})),maxX=Math.max(1,...rows.map(r=>Math.min(90,r.m.daysCover))),maxY=Math.max(1,...rows.map(r=>r.m.margin/7));return`<svg class="data-chart scatter" viewBox="0 0 600 290" role="img" aria-label="Пузыри: запас в днях и средняя дневная маржа. Размер зависит от остатка."><line x1="45" y1="240" x2="570" y2="240" stroke="#bdcbbb"/><line x1="45" y1="20" x2="45" y2="240" stroke="#bdcbbb"/><text x="300" y="278" text-anchor="middle" fill="#7c8b78" font-size="12">Запас в днях (максимум 90)</text><text x="55" y="15" fill="#7c8b78" font-size="11">Маржа / день, ₽</text>${rows.map(({p,m},i)=>`<circle cx="${45+(Number.isFinite(m.daysCover)?Math.min(90,m.daysCover):maxX)/maxX*480}" cy="${240-Math.max(0,m.margin/7)/maxY*200}" r="${6+Math.sqrt(p.stock)*.8}" fill="${colors[i%8]}" opacity=".7"><title>${esc(p.name)}: запас ${Number.isFinite(m.daysCover)?m.daysCover.toFixed(1):'∞'} дн., маржа ${money(m.margin/7)}/день</title></circle>`).join('')}</svg>`;}
export const metricHelp={riskCount:'Число товаров со сроком партии не больше 5 дней и остатком выше ожидаемых продаж до конца срока.',lowStock:'Число товаров, где запаса в днях меньше срока пополнения.',weakCards:'Число карточек с заполненностью ниже 80% или менее двух фото.',revenue:'Сумма выручки по строкам продаж за выбранный период.',margin:'Выручка минус проданные единицы × текущая себестоимость. Это не чистая прибыль.',marginRate:'Валовая маржа / выручка. Не включает доставку, налоги и комиссии.',avgUnit:'Выручка / проданные единицы. Не средний чек заказа: заказов в исходных данных нет.',unitMargin:'Валовая маржа / проданные единицы.',avgDaily:'Выручка / число дней в выбранном периоде.',change:'Изменение выручки относительно предыдущего периода той же длины. Не доказывает причин.',stockCost:'Остаток × текущая себестоимость по всем товарам.',stockRetail:'Остаток × текущая цена. Это стоимость запасов по прайсу, не прогноз продаж.',riskCost:'Излишек над ожидаемым спросом до срока партии × себестоимость. Спрос условно постоянен.',cv:'Стандартное отклонение дневной выручки / её среднее. Больше значение, сильнее колебания.',avgCard:'Средняя заполненность карточек, введённая пользователем. Не автоматическая оценка содержания.',consented:'Сумма согласий из обезличенных агрегатов. Перед реальной отправкой проверяются в CRM.'};
export function renderAnalytics(data,days=28){const m=advancedMetrics(data,days),items=[['revenue','Выручка',money(m.revenue)],['margin','Валовая маржа',money(m.margin)],['marginRate','Маржинальность',(m.marginRate*100).toFixed(1)+'%'],['avgUnit','Средняя цена единицы',money(m.avgUnit)],['unitMargin','Маржа на единицу',money(m.unitMargin)],['avgDaily','Выручка в день',money(m.avgDaily)],['change','К прошлому периоду',m.change===null?'Нет базы':(m.change>=0?'+':'')+(m.change*100).toFixed(1)+'%'],['stockCost','Деньги в запасах',money(m.stockCost)],['stockRetail','Запас по прайсу',money(m.stockRetail)],['riskCost','Себестоимость под риском',money(m.riskCost)],['cv','Колебания выручки',(m.cv*100).toFixed(0)+'%'],['avgCard','Заполненность карточек',Math.round(m.avgCard)+'%'],['riskCount','Партий под риском',m.riskCount+' поз.'],['lowStock','Риск дефицита',m.lowStock+' поз.'],['weakCards','Слабые карточки',m.weakCards+' поз.'],['consented','Согласия на сообщения',m.consented+' чел.']];const abcRows=abc(data,days);return`<section class="page-heading"><div><p class="eyebrow">ПАНОРАМА ФЕРМЫ</p><h1>Цифры становятся<br><em>понятнее.</em></h1><p class="subhead">16 показателей, пять видов графиков и конкретные пояснения.</p></div><label class="select-label">Период<select id="insight-period"><option value="7" ${days===7?'selected':''}>7 дней</option><option value="28" ${days===28?'selected':''}>28 дней</option></select></label></section><div class="metric-grid">${items.map(([k,label,value])=>`<article class="metric-tile"><button class="metric-help" data-metric="${k}" aria-label="Как считается: ${label}">?</button><span>${label}</span><strong>${value}</strong><small>${esc(metricHelp[k])}</small></article>`).join('')}</div><div class="panel analytics-chart"><div class="panel-head"><h2>Выручка и валовая маржа</h2><span class="badge soft">Линейный график</span></div>${linePlot(dailySeries(data,null,days),['revenue','margin'],['Выручка','Маржа'])}</div><div class="bottom-grid equal"><div class="panel"><div class="panel-head"><h2>Откуда приходит выручка</h2><span class="badge soft">Кольцевая диаграмма</span></div>${donut(data)}<p class="fine-print">За 28 дней. Не сравнивайте категории только по доле, учитывайте маржу и остаток.</p></div><div class="panel"><div class="panel-head"><h2>Запас и отдача товара</h2><span class="badge soft">Пузырьковая диаграмма</span></div>${scatter(data)}<p class="fine-print">Наведите на точку, чтобы увидеть товар. Размер точки зависит от остатка; запас свыше 90 дней ограничен на графике.</p></div></div><div class="panel analytics-chart"><div class="panel-head"><h2>Когда покупают ваши товары</h2><span class="badge soft">Тепловая карта</span></div>${heatmap(data)}<p class="fine-print">Среднее количество единиц по дням недели из всей истории. Это исторический рисунок, не доказанная сезонность.</p></div><div class="panel analytics-chart"><div class="panel-head"><h2>ABC: вклад товаров в выручку</h2><button class="btn secondary" data-act="explain-abc">Как читать ABC?</button></div><div class="table-scroll"><table><thead><tr><th>Товар</th><th>Группа</th><th>Выручка</th><th>Доля</th><th>Накопленная доля</th><th>Валовая маржа</th></tr></thead><tbody>${abcRows.map(r=>`<tr><td>${esc(r.p.name)}</td><td><span class="abc ${r.group}">${r.group}</span></td><td>${money(r.revenue)}</td><td>${(r.share*100).toFixed(1)}%</td><td><div class="abc-bar"><i style="width:${r.cumulative*100}%"></i></div>${(r.cumulative*100).toFixed(1)}%</td><td>${money(r.margin)}</td></tr>`).join('')}</tbody></table></div><p class="fine-print">A: товары до границы 80% накопленной выручки, B до 95%, C остальные. Группа не является советом убрать товар.</p></div>`;}
export function renderForecast(data,id,horizon=7,method='weekday'){id=id||data.products[0].id;const f=forecast(data,id,horizon,method),p=data.products.find(p=>p.id===id);return`<section class="page-heading"><div><p class="eyebrow">ПОСМОТРЕТЬ ВПЕРЁД</p><h1>Спрос на завтра.<br><em>С запасом на неизвестное.</em></h1><p class="subhead">Прогноз количества, проверка на истории и план пополнения.</p></div></section><div class="forecast-controls panel"><label class="field">Товар<select id="forecast-product">${data.products.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Горизонт<select id="forecast-horizon">${[7,14,30].map(n=>`<option value="${n}" ${n===horizon?'selected':''}>${n} дней</option>`).join('')}</select></label><label class="field">Метод<select id="forecast-method"><option value="weekday" ${method==='weekday'?'selected':''}>Среднее + день недели</option><option value="average" ${method==='average'?'selected':''}>Среднее последних 7 дней</option></select></label></div>${!f.valid?`<div class="callout">${esc(f.reason)}</div>`:`<div class="forecast-summary"><div class="forecast-primary"><p class="eyebrow">СЦЕНАРИЙ НА ${horizon} ДНЕЙ</p><strong>${Math.round(f.total)} <small>${esc(p.unit)}</small></strong><p>Диапазон ${Math.floor(f.low)}–${Math.ceil(f.high)} ${esc(p.unit)}. Не гарантия и не доверительный интервал.</p></div><div><span>Остаток сейчас</span><b>${p.stock} ${esc(p.unit)}</b></div><div><span>Пополнить за горизонт (с учётом срока)</span><b>${f.needed} ${esc(p.unit)}</b></div><div><span>Запаса примерно на</span><b>${f.daysCover===null?'Нет темпа':f.daysCover.toFixed(1)+' дн.'}</b></div></div><div class="panel"><div class="panel-head"><h2>История и ожидаемый спрос</h2><span class="badge purple">Прогноз справа от линии</span></div>${forecastPlot(f)}<div class="legend"><span><i style="background:#327d76"></i>Факт, единиц</span><span><i style="background:#b586b1"></i>Средний сценарий</span><span><i style="background:#e1d4e6"></i>Диапазон неопределённости</span></div></div><div class="bottom-grid equal"><div class="panel"><h2>Как модель прошла проверку</h2><div class="backtest-metrics"><div><b>${f.mae.toFixed(1)}</b><span>MAE, ошибка в единицах</span></div><div><b>${f.wape===null?'Нет базы':Math.round(f.wape*100)+'%'}</b><span>WAPE, суммарная относительная ошибка</span></div></div><p>Последние ${f.tests.length} дней предсказывались последовательно только по более ранним данным. Будущее в обучение не подставлялось.</p><button class="btn secondary" data-act="forecast-help">Объясните без терминов</button></div><div class="panel"><h2>Перед пополнением проверьте</h2><ul class="plain-list"><li>Срок хранения партии и доступность поставки. Остаток после срока не считается доступным для будущего спроса.</li><li>Акции, праздники и погоду, которых нет в модели.</li><li>Остатки, возвраты и спрос вне вашего магазина.</li><li>Насколько много пропущенных дней в исходных данных.</li></ul><p class="fine-print">Горизонт 30 дней особенно неопределён. Полоса расширяется с горизонтом, но не имеет статистической калибровки покрытия.</p></div></div>`}`;}
export function forecastPlot(f){const rows=[...f.series,...f.future],w=900,h=270,pad=36,max=Math.max(1,...rows.map(r=>r.high??r.units))*1.1;const xy=(r,i,key='units')=>`${pad+i*(w-60)/(rows.length-1)},${h-25-(r[key]??r.units)/max*(h-55)}`;const start=f.series.length;const band=[...f.future.map((r,i)=>xy(r,start+i,'high')),...[...f.future].reverse().map((r,i)=>xy(r,rows.length-1-i,'low'))].join(' ');return`<svg viewBox="0 0 ${w} ${h+20}" class="data-chart" role="img" aria-label="История и сценарный диапазон будущего спроса"><line x1="36" y1="245" x2="870" y2="245" stroke="#cfdbcb"/><polygon points="${band}" fill="#e1d4e6" opacity=".7"/><polyline points="${f.series.map(xy).join(' ')}" fill="none" stroke="#327d76" stroke-width="3"/><polyline points="${f.future.map((r,i)=>xy(r,start+i)).join(' ')}" fill="none" stroke="#a275a2" stroke-width="3" stroke-dasharray="6 4"/><line x1="${pad+(start-.5)*(w-60)/(rows.length-1)}" x2="${pad+(start-.5)*(w-60)/(rows.length-1)}" y1="20" y2="250" stroke="#b7b8ae" stroke-dasharray="3 4"/>${rows.filter((_,i)=>i%Math.ceil(rows.length/8)===0||i===rows.length-1).map(r=>`<text x="${pad+rows.indexOf(r)*(w-60)/(rows.length-1)}" y="280" text-anchor="middle" fill="#84927c" font-size="11">${r.date.slice(8)}.${r.date.slice(5,7)}</text>`).join('')}</svg>`;}
export function renderLab(data){return`<section class="page-heading"><div><p class="eyebrow">ПРОВЕРИТЬ ИДЕЮ ДО ЗАПУСКА</p><h1>А что, если<br><em>изменить условия?</em></h1><p class="subhead">Симулятор экономики товара. Это заданный вами сценарий, не прогноз LLM.</p></div></section><div class="bottom-grid equal"><div class="panel"><h2>Цена, спрос и расходы</h2><label class="field">Товар<select id="lab-product">${data.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label class="field">Изменение цены, %<input type="range" id="lab-price" min="-30" max="30" value="0"><output id="lab-price-label">0%</output></label><label class="field">Предполагаемое изменение спроса, %<input type="range" id="lab-demand" min="-60" max="100" value="0"><output id="lab-demand-label">0%</output></label><label class="field">Дополнительные расходы на 7 дней, ₽<input type="number" id="lab-expense" min="0" max="1000000" value="0"></label><p class="fine-print">Спрос вы задаёте сами. Для большинства товаров его реакция на цену без эксперимента неизвестна.</p></div><div class="panel"><p class="eyebrow">СЦЕНАРНАЯ ЭКОНОМИКА</p><h2>До и после</h2><div id="lab-result"></div><button class="btn secondary" data-act="lab-reset">Вернуть исходные условия</button><p class="fine-print">Продажи ограничены текущим остатком. Запасы, налоги и будущая поставка не моделируются. Цены нигде не меняются.</p></div></div>`;}
export function simulate(data,id,priceChange,demandChange,expense){const p=data.products.find(p=>p.id===id);if(!p)throw Error('Неизвестный товар');const m=metrics(data,id),price=p.price*(1+clamp(Number(priceChange)||0,-30,30)/100),units=Math.min(p.stock,m.units*(1+clamp(Number(demandChange)||0,-60,100)/100)),cost=clamp(Number(expense)||0,0,1e6),baseUnits=Math.min(p.stock,m.units),base=baseUnits*(p.price-p.cost),profit=units*(price-p.cost)-cost;return{price,units,base,profit,delta:profit-base,revenue:price*units,expenses:p.cost*units+cost,breakEven:price>p.cost?Math.ceil((base+cost)/(price-p.cost)):null};}
